#include <cstddef>
#include <cstdint>
#include <vector>

static std::size_t modrmLength(const std::vector<std::uint8_t>& code, std::size_t at)
{
    if (at >= code.size()) return 0;
    const std::uint8_t m{ code[at] };
    const int mod{ m >> 6 }, rm{ m & 7 };
    std::size_t length{ 1 };
    if (mod == 3) return length;
    if (rm == 4)
    {
        if (at + 1 >= code.size()) return 0;
        ++length;
        if (mod == 0 && (code[at + 1] & 7) == 5) length += 4;
    }
    else if (mod == 0 && rm == 5) length += 4;
    if (mod == 1) length += 1;
    if (mod == 2) length += 4;
    return length;
}

std::size_t instructionLength(const std::vector<std::uint8_t>& code, std::size_t at)
{
    std::size_t i{ at };
    bool opsize{ false }, rexW{ false };
    while (i < code.size() && (code[i] == 0x66 || code[i] == 0xF2 || code[i] == 0xF3)) { if (code[i] == 0x66) opsize = true; ++i; }
    if (i < code.size() && code[i] >= 0x40 && code[i] <= 0x4F) { rexW = (code[i] & 8) != 0; ++i; }
    if (i >= code.size()) return 0;
    const std::uint8_t op{ code[i++] };
    std::size_t rest{ 0 };
    const auto withModrm = [&](std::size_t immediate) -> std::size_t {
        const std::size_t m{ modrmLength(code, i) };
        return m ? m + immediate : 0;
    };
    if ((op >= 0x50 && op <= 0x5F) || op == 0x90 || op == 0xC3 || op == 0xCC) rest = 0;
    else if ((op >= 0x70 && op <= 0x7F) || op == 0xEB) rest = 1;
    else if (op == 0xE8 || op == 0xE9) rest = 4;
    else if (op >= 0xB8 && op <= 0xBF) rest = rexW ? 8 : 4;
    else if (op == 0x01 || op == 0x03 || op == 0x29 || op == 0x2B || op == 0x31 || op == 0x33 || op == 0x39 || op == 0x3B
             || op == 0x63 || op == 0x85 || op == 0x89 || op == 0x8B || op == 0x8D) { rest = withModrm(0); if (!rest) return 0; }
    else if (op == 0x83) { rest = withModrm(1); if (!rest) return 0; }
    else if (op == 0x81 || op == 0xC7) { rest = withModrm(opsize ? 2 : 4); if (!rest) return 0; }
    else if (op == 0x0F)
    {
        if (i >= code.size()) return 0;
        const std::uint8_t op2{ code[i++] };
        if (op2 >= 0x80 && op2 <= 0x8F) rest = 4;
        else if (op2 == 0x1F || op2 == 0xB6 || op2 == 0xB7 || op2 == 0xBE || op2 == 0xBF) { rest = withModrm(0); if (!rest) return 0; }
        else return 0;
    }
    else return 0;
    const std::size_t total{ i - at + rest };
    if (at + total > code.size()) return 0;
    return total;
}

