using Bytes = std::vector<std::uint8_t>;
static std::size_t len(Bytes b) { return instructionLength(b, 0); }

TEST("one-byte instructions and short forms") {
    CHECK_EQ(len({ 0x55 }), 1u);
    CHECK_EQ(len({ 0x41, 0x5C }), 2u);
    CHECK_EQ(len({ 0xC3 }), 1u);
    CHECK_EQ(len({ 0x74, 0x0C }), 2u);
    CHECK_EQ(len({ 0xE8, 1, 2, 3, 4 }), 5u);
    CHECK_EQ(len({ 0x0F, 0x85, 0, 1, 0, 0 }), 6u);
}
TEST("immediates") {
    CHECK_EQ(len({ 0xB8, 1, 0, 0, 0 }), 5u);
    CHECK_EQ(len({ 0x48, 0xB8, 1, 2, 3, 4, 5, 6, 7, 8 }), 10u);
    CHECK_EQ(len({ 0x48, 0x83, 0xEC, 0x20 }), 4u);
    CHECK_EQ(len({ 0x48, 0x81, 0xEC, 0x50, 0x01, 0x00, 0x00 }), 7u);
    CHECK_EQ(len({ 0x66, 0x81, 0xC1, 0x34, 0x12 }), 5u);
    CHECK_EQ(len({ 0xC7, 0x45, 0xF8, 0x0A, 0x00, 0x00, 0x00 }), 7u);
}
TEST("ModRM and SIB forms") {
    CHECK_EQ(len({ 0x48, 0x89, 0xE5 }), 3u);
    CHECK_EQ(len({ 0x8B, 0x45, 0xFC }), 3u);
    CHECK_EQ(len({ 0x48, 0x8D, 0x0D, 0x10, 0x00, 0x00, 0x00 }), 7u);
    CHECK_EQ(len({ 0x48, 0x8B, 0x04, 0xC8 }), 4u);
    CHECK_EQ(len({ 0x4C, 0x8B, 0x44, 0x24, 0x28 }), 5u);
    CHECK_EQ(len({ 0x48, 0x89, 0x5C, 0x24, 0x08 }), 5u);
    CHECK_EQ(len({ 0x8B, 0x04, 0x25, 0x10, 0x00, 0x00, 0x00 }), 7u);
    CHECK_EQ(len({ 0x89, 0x84, 0x24, 0x00, 0x01, 0x00, 0x00 }), 7u);
    CHECK_EQ(len({ 0x0F, 0xB6, 0x41, 0x18 }), 4u);
    CHECK_EQ(len({ 0x0F, 0x1F, 0x44, 0x00, 0x00 }), 5u);
    CHECK_EQ(len({ 0x48, 0x63, 0xC1 }), 3u);
}
TEST("unknown and truncated") {
    CHECK_EQ(len({ 0x0F, 0x0B }), 0u);
    CHECK_EQ(len({ 0xF4 }), 0u);
    CHECK_EQ(len({ 0xE8, 1, 2 }), 0u);
    CHECK_EQ(len({ 0x48 }), 0u);
    CHECK_EQ(len({ 0x48, 0x89 }), 0u);
    CHECK_EQ(len({}), 0u);
    CHECK_EQ(instructionLength({ 0x90, 0x55, 0x48, 0x89, 0xE5 }, 2), 3u);
}

